(function(root){
'use strict';
const candidates=typeof module==='object'&&module.exports?require('./library.js').cases:root.NavigatorLibrary.getCases();
const checked=c=>c.verificationLevel==='primary-verified'&&c.verifiedAt&&/^[a-f0-9]{64}$/.test(c.sourceSha256||'')&&['identity','primaryText','proposition','pinpoint','disposition'].every(k=>c.verification?.[k]===true);
const readable=c=>checked(c)||c.verificationLevel==='public-court-text';
const data=candidates.filter(readable);
const tierOptions=['Core authority','Supporting authority','Context or case history','Procedural orders','Other authorities'];
const tier=c=>c.publicationTier||'Other authorities';
const leading=new Map([['C05',8.1],['C06',8.2]]);
const rank=c=>c.publicationRank??leading.get(c.id)??Infinity;
const getForumOptions=()=>[...new Set(data.map(c=>kind(c).split(' · ')[0].split(/ judgment| order/i)[0]))].sort();
const publicNumbers=new Map(data.map((c,i)=>[c.id,c.directoryNumber]));
const numberFor=id=>publicNumbers.get(id);
const kind=c=>c.decisionType||(/Commission/i.test(c.forum)?'Information Commission order':/Tribunal/i.test(c.forum)?'Tribunal order':/Supreme/i.test(c.forum)?'Supreme Court judgment / order':'High Court judgment / order');
const forumOptions=getForumOptions();
const normal=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const topics=[...new Set(data.flatMap(c=>(c.topics?.length?c.topics:['Other POSH authorities'])))].sort();
function filter(q='',topic='All topics',type='All forums',use='All uses'){const words=normal(q).split(' ').filter(Boolean),serial=normal(q).match(/^judgment ?0*(\d+)$/);return data.filter(c=>(topic==='All topics'||((c.topics?.length?c.topics:['Other POSH authorities'])).includes(topic))&&(type==='All forums'||kind(c).startsWith(type))&&(use==='All uses'||tier(c)===use)&&(serial?Number(numberFor(c.id))===Number(serial[1]):words.every(w=>normal(['Judgment '+numberFor(c.id),c.id,c.masterId,c.title,c.caseNumber,c.citation,c.date,c.basis,c.note,c.caution,c.pinpoint,c.decisionType,tier(c),...(c.linkedOrders||[]).flatMap(o=>[o.date,o.docket,o.type]),...(c.topics||[])].join(' ')).includes(w)))).sort((a,b)=>rank(a)-rank(b)||a.directoryNumber.localeCompare(b.directoryNumber));}
if(typeof module==='object'&&module.exports){module.exports={data,checked,kind,filter,topics,numberFor,tier};return;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderOrders(c){
  if(!c.linkedOrders?.length)return '';
  return `<div class="case-source-status"><strong>Related orders</strong><ul>${c.linkedOrders.map(order=>`
    <li><strong>${esc(order.date)} · ${esc(order.type)}</strong>
      <p>${esc(order.docket)}. ${esc(order.note)}${order.sourceNote?' '+esc(order.sourceNote):''}</p>
      ${order.url?`<a href="${esc(order.url)}" target="_blank" rel="noopener noreferrer">Read this order ↗</a>`:''}
      ${order.archive?`<a href="${esc(order.archive)}" target="_blank" rel="noopener noreferrer">Find this order in the court archive ↗</a>`:''}
    </li>`).join('')}</ul></div>`;
}
function render(app,path){let page=0;const params=new URLSearchParams(location.hash.split('?')[1]||''),selected=path.startsWith('faq/case-')?data.find(c=>c.id===path.split('case-')[1].toUpperCase()):null;const previousFAQ=selected&&root.NavigatorFinder.recordFor(params.get('from'));app.innerHTML=`<section class="app-heading"><div class="wrap"><div><a class="app-back" href="${previousFAQ?'#faq/'+esc(previousFAQ.id):'#faq'}">← ${previousFAQ?'Back to FAQ '+esc(previousFAQ.number):'FAQs'}</a><small>THE COSMIC ENERGIZERS · CASE LAW</small><h1>POSH judgments and orders</h1><p>Browse ${data.length} court decisions by issue. Each record shows what the court decided, where to read it, and how far the decision applies.</p><nav class="knowledge-tabs" aria-label="Knowledge library"><a href="#faq">All FAQs <strong>${root.NavigatorFinder.count}</strong></a><a href="#faq/cases" aria-current="page">Judgments &amp; orders <strong>${data.length}</strong></a></nav></div></div></section><div class="app-bg"><div class="wrap workspace finder-shell"><section class="finder-controls"><label for="case-search">Search case name, citation, section or issue</label><input id="case-search" type="search" maxlength="160" autocomplete="off" placeholder="Try: employer, Director, 534/2026 or Judgment 015"><div class="case-filters"><label>Issue<select id="case-topic"><option>All topics</option>${topics.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label>Forum<select id="case-forum"><option>All forums</option>${forumOptions.map(f=>`<option>${esc(f)}</option>`).join('')}</select></label><label>Use<select id="case-use"><option>All uses</option>${tierOptions.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label></div><button id="case-reset" class="btn btn-light" type="button">Show all authorities</button></section><p class="faq-general-note">Start with core and supporting authorities. Context and procedural records show how related matters progressed. Check the limits and any linked orders before citing a case.</p><p id="case-count" role="status" aria-live="polite"></p><div id="case-results"></div><p id="case-empty" hidden>No matching judgment or order. Choose “Show all authorities” to browse the full collection.</p><nav class="library-pagination" aria-label="Case pages"><button id="case-prev" type="button" class="btn btn-light">Previous</button><span id="case-page"></span><button id="case-next" type="button" class="btn btn-light">Next</button></nav></div></div>`;
const input=app.querySelector('#case-search'),topic=app.querySelector('#case-topic'),forum=app.querySelector('#case-forum'),use=app.querySelector('#case-use');input.value=selected?'Judgment '+numberFor(selected.id):path.startsWith('faq/case-')?'unavailable-reference':(params.get('q')||'').slice(0,160);if(topics.includes(params.get('topic')))topic.value=params.get('topic');if(forumOptions.includes(params.get('forum')))forum.value=params.get('forum');if(tierOptions.includes(params.get('use')))use.value=params.get('use');page=Math.max(0,(parseInt(params.get('page'),10)||1)-1);
function apply(persist=true){const list=filter(input.value,topic.value,forum.value,use.value);page=Math.min(page,Math.max(0,Math.ceil(list.length/12)-1));const visible=list.slice(page*12,page*12+12);app.querySelector('#case-count').textContent=`${list.length} of ${data.length} authorities · ${list.filter(checked).length} court PDFs checked`;app.querySelector('#case-results').innerHTML=visible.map(c=>{const related=[...new Map([...(c.relatedFAQs||[]).map(id=>root.NavigatorFinder.recordFor(id)),...root.NavigatorFinder.getIndex().filter(x=>(x.cases||[]).includes(c.id)||x.members.some(m=>(m.cases||[]).includes(c.id)))].filter(Boolean).map(x=>[x.id,x])).values()].slice(0,5);return `<article class="case-record" id="case-${c.id.toLowerCase()}" data-case-id="${c.id}"><div class="case-record-meta"><span>Judgment ${numberFor(c.id)}</span><span>${esc(kind(c))}</span><span>${esc(tier(c))}</span><span>${checked(c)?(c.sourceHost==='publisher'?'Court text checked · hosted copy':'Court PDF checked'):'Public court text checked'}</span></div><h2>${esc(c.title)}</h2><p class="case-citation"><strong>Citation / docket:</strong> ${esc(c.caseNumber||c.citation||'Citation identity requires verification')} · ${esc(c.date||'Decision date requires verification')}</p>${c.citation&&c.caseNumber?`<p class="case-citation"><strong>Citation:</strong> ${esc(c.citation)}</p>`:''}<p><strong>Forum:</strong> ${esc(c.forum||'Forum requires verification')}</p>${c.note?`<p><strong>Legal point:</strong> ${esc(c.note)}</p>`:'<p>The precise proposition remains a research task. Read the source and verification status before citing this record.</p>'}${c.basis?`<p><strong>Provisions / framework:</strong> ${esc(c.basis)}</p>`:''}${c.pinpoint?`<p><strong>Pinpoint:</strong> ${esc(c.pinpoint)}</p>`:''}${c.caution?`<p><strong>Limits:</strong> ${esc(c.caution)}</p>`:''}<details class="case-source-status"><summary>Verification and subsequent-proceeding details</summary><p>${esc(c.status)}</p>${c.checkedAt?`<p>Source checked ${esc(c.checkedAt)}</p>`:''}${c.laterSource?`<p><a href="${esc(c.laterSource)}" target="_blank" rel="noopener noreferrer">Read the inspected later order ↗</a></p>`:''}${c.serviceRules?`<p>Service rules: ${esc(c.serviceRules)}</p>`:''}</details>${renderOrders(c)}<nav class="case-source-links">${c.url?`<a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${checked(c)?'Read judgment or order ↗':'Read public court text ↗'}</a>`:'<span>Original source link not yet established.</span>'}${c.corroboratingUrl?`<a href="${esc(c.corroboratingUrl)}" target="_blank" rel="noopener noreferrer">Cross-check court text ↗</a>`:''}${c.sourceArchive?`<a href="${esc(c.sourceArchive)}" target="_blank" rel="noopener noreferrer">Search Supreme Court archive ↗</a>`:''}<a href="#faq/case-${c.id.toLowerCase()}">Link to this decision</a></nav>${related.length?`<nav class="faq-related" aria-label="Related FAQs"><strong>Related FAQs</strong>${related.map(x=>`<a href="#faq/${esc(x.id)}">FAQ ${x.number} · ${esc(x.question)}</a>`).join('')}</nav>`:''}</article>`}).join('');app.querySelector('#case-empty').hidden=!!list.length;app.querySelector('#case-prev').disabled=page===0;app.querySelector('#case-next').disabled=(page+1)*12>=list.length;app.querySelector('#case-page').textContent=`Page ${page+1} of ${Math.max(1,Math.ceil(list.length/12))}`;if(persist){const p=new URLSearchParams();if(input.value)p.set('q',input.value);if(topic.value!=='All topics')p.set('topic',topic.value);if(use.value!=='All uses')p.set('use',use.value);if(forum.value!=='All forums')p.set('forum',forum.value);if(page)p.set('page',String(page+1));history.replaceState(null,'','#faq/cases'+(p.size?'?'+p.toString():''));}}
for(const el of [input,topic,forum,use])el.addEventListener(el===input?'input':'change',()=>{page=0;apply()});app.querySelector('#case-reset').onclick=()=>{input.value='';topic.value='All topics';forum.value='All forums';use.value='All uses';page=0;apply();};const focus=()=>{app.querySelector('#case-count').scrollIntoView({block:'start'});};app.querySelector('#case-prev').onclick=()=>{page--;apply();focus()};app.querySelector('#case-next').onclick=()=>{page++;apply();focus()};apply(false);document.title=`${data.length} POSH judgments and orders | The Cosmic Energizers`;
}
root.NavigatorCases={render,count:data.length};
})(typeof window==='undefined'?globalThis:window);
